const item = $input.first().json;
const from = String(item.from?.text || item.from || '').toLowerCase();
const sub = String(item.subject || '').toLowerCase();
const metaSenders = ['facebookmail.com', 'meta.com', 'fb.com', 'facebook.com'];
const isMeta = metaSenders.some(s => from.includes(s));
const isInvoice = /rechnung|invoice|receipt|beleg|billing|abrechnung/.test(sub);
if (!isMeta || !isInvoice) return [];
return [{ json: item }];

